#!/bin/bash
# Heap guard for crawl boxes box1 (v2) and box5. Four files, all or nothing:
#   crawler  src/heapGuard.js (new), src/standalone.js, scripts/run-daily-crawl.mjs
#   sync     ~/inventory-sync/syncSweepGuard.js  (reads the crawl log line "🧠 <store>: heap ... stopped this store" and keeps that store out of the sweep)
# Self-contained: the patches and heapGuard.js are embedded below, so `check` stages nothing on the box. Run ON the box from STDIN:
#
#   ssh box1 'bash -s -- check'    < install.sh     # READ-ONLY on the box's code: gates, md5s, zero-fuzz trial on copies in a mktemp dir (removed on exit)
#   ssh box1 'bash -s -- apply'    < install.sh     # check, backup, install, verify; restores itself on any failure
#   ssh box1 'bash -s -- restore'  < install.sh     # put the backed-up files back, remove heapGuard.js
#
# REFUSES (exit 1, nothing written) on: a crawl/sync running, 21:30-07:00 ET, a file whose md5 is not a known state.
# No restart, no cron or env change: the next crawl / sync is a fresh Node process. The guard is on by default; CRAWLER_HEAP_GUARD_RATIO=0 turns it off.
set -u
C=${HEAPGUARD_CRAWLER_DIR:-/home/ubuntu/nj-scraper/scrapers/lightsail-crawler}
SYNCD=${HEAPGUARD_SYNC_DIR:-/home/ubuntu/inventory-sync}
BK=${HEAPGUARD_BACKUP:-/home/ubuntu/backups/heap-guard-20261106}
SRC=$C/src; DRV=$C/scripts/run-daily-crawl.mjs; SA=$SRC/standalone.js; HG=$SRC/heapGuard.js; SG=$SYNCD/syncSweepGuard.js
HG_MD5=452ce895cc5c82e86ae2b7b26a86ca48; SG_BEFORE=c9c3ccf43cdbe55c81ebde99df1cb77e; SG_AFTER=25e105a457147c19891abd275b8ef7d6
B1_SA=8c39cf86d3017210d586ff3afeb33969;  B1_DR=89b6bb521c564bd2fb2f564f91f135b3;  B1_SA_AFTER=f81fbd6177e06a4060230ff9b383c4ca;  B1_DR_AFTER=479661a3b44161cc0632aff44d8b48e3
B5_SA=2e69d8748b9addbff93dac618bb71f1e;  B5_DR=f3d6c4b508e94b067a3a817b55675b70;  B5_SA_AFTER=752cf191c2a71dee0fd0b23568dc28d5;  B5_DR_AFTER=1b4ce62b7d0884f3f4b473974b2533cf

fail() { echo "REFUSED: $*" >&2; exit 1; }
md5of() { md5sum "$1" | cut -d' ' -f1; }
MODE=${1:-check}

if [ "$MODE" = restore ]; then
  [ -f "$BK/md5s-before.txt" ] || fail "no backup at $BK"
  for f in standalone.js run-daily-crawl.mjs syncSweepGuard.js; do
    want=$(awk -v f=$f '$2==f{print $1}' "$BK/md5s-before.txt"); [ "$(md5of "$BK/$f.before")" = "$want" ] || fail "backup $f does not match its recorded md5"
  done
  cp -p "$BK/standalone.js.before" "$SA.rb" && mv -f "$SA.rb" "$SA"
  cp -p "$BK/run-daily-crawl.mjs.before" "$DRV.rb" && mv -f "$DRV.rb" "$DRV"
  cp -p "$BK/syncSweepGuard.js.before" "$SG.rb" && mv -f "$SG.rb" "$SG"
  rm -f "$HG"
  echo "restored: standalone.js $(md5of "$SA"), run-daily-crawl.mjs $(md5of "$DRV"), syncSweepGuard.js $(md5of "$SG"), heapGuard.js removed"; exit 0
fi
[ "$MODE" = check ] || [ "$MODE" = apply ] || fail "mode must be check, apply or restore (got '$MODE')"

now=$(TZ=America/New_York date +%H%M)
if [ $((10#$now)) -ge 2130 ] || [ $((10#$now)) -lt 700 ]; then fail "it is $now ET: installs only 07:00-21:30 ET (crons start at 22:00)"; fi
busy=$( { pgrep -a -x node | grep -E 'src/standalone|inventory-sync|run-daily-crawl'; pgrep -af '^(/bin/|/usr/bin/)?bash [^ ]*(run-daily-crawl|run_nightly_chain|run_sync_when_safe)'; } 2>/dev/null | grep -v pgrep )
[ -z "$busy" ] || fail "a crawl or sync is running: $busy"
for f in "$SA" "$DRV" "$SG"; do [ -f "$f" ] || fail "$f not found (wrong box or path)"; done
node -e 'process.exit(typeof structuredClone==="function"?0:1)' || fail "this node has no structuredClone ($(node -v))"

sa=$(md5of "$SA"); dr=$(md5of "$DRV"); sg=$(md5of "$SG"); BOX=
case "$sg" in "$SG_BEFORE") SG_DONE=0;; "$SG_AFTER") SG_DONE=1;; *) fail "syncSweepGuard.js md5 $sg is not a known state ($SG_BEFORE before / $SG_AFTER after). Send the file back; do not improvise.";; esac
CR_DONE=0
case "$sa:$dr" in
  "$B1_SA:$B1_DR") BOX=b1; SA_AFTER=$B1_SA_AFTER; DR_AFTER=$B1_DR_AFTER; echo "box1 variant (standalone $sa, driver $dr)";;
  "$B5_SA:$B5_DR") BOX=b5; SA_AFTER=$B5_SA_AFTER; DR_AFTER=$B5_DR_AFTER; echo "box5 variant (standalone $sa, driver $dr)";;
  "$B1_SA_AFTER:$B1_DR_AFTER"|"$B5_SA_AFTER:$B5_DR_AFTER") CR_DONE=1;;
  *) fail "standalone.js md5 $sa / run-daily-crawl.mjs md5 $dr is not a known state (box1 $B1_SA/$B1_DR, box5 $B5_SA/$B5_DR). Send the files back; do not improvise.";;
esac
if [ "$CR_DONE" = 1 ]; then
  [ -f "$HG" ] && [ "$(md5of "$HG")" = "$HG_MD5" ] || fail "crawler files are patched but heapGuard.js is missing or not the pinned file"
  [ "$SG_DONE" = 1 ] && { echo "ALREADY INSTALLED, nothing to do."; exit 0; }
  fail "crawler files already patched; only syncSweepGuard.js is missing — send this output back, do not improvise"
fi
[ ! -e "$HG" ] || [ "$(md5of "$HG")" = "$HG_MD5" ] || fail "$HG exists with an unexpected md5"

W=$(mktemp -d /tmp/heapguard-trial.XXXXXX) || fail "cannot make a temp dir"
trap 'rm -rf "$W"' EXIT
mkdir -p "$W/src" "$W/scripts" "$W/sync"
emit_hg()      { base64 -d <<'HGEOF'

HGEOF
}
emit_sa_b1()   { base64 -d <<'EOF1'

EOF1
}
emit_sa_b5()   { base64 -d <<'EOF2'

EOF2
}
emit_dr_b1()   { base64 -d <<'EOF3'

EOF3
}
emit_dr_b5()   { base64 -d <<'EOF4'

EOF4
}
emit_sg()      { base64 -d <<'EOF5'

EOF5
}
emit_hg > "$W/src/heapGuard.js"; [ "$(md5of "$W/src/heapGuard.js")" = "$HG_MD5" ] || fail "embedded heapGuard.js md5 wrong"
emit_sa_$BOX > "$W/sa.patch"; emit_dr_$BOX > "$W/dr.patch"; emit_sg > "$W/sg.patch"
cp -p "$SA" "$W/src/standalone.js"; cp -p "$DRV" "$W/scripts/run-daily-crawl.mjs"; cp -p "$SG" "$W/sync/syncSweepGuard.js"
(cd "$W" && patch -p1 -s -F0 --no-backup-if-mismatch < sa.patch) || fail "standalone patch does not apply (zero fuzz)"
(cd "$W" && patch -p1 -s -F0 --no-backup-if-mismatch < dr.patch) || fail "driver patch does not apply (zero fuzz)"
if [ "$SG_DONE" = 0 ]; then (cd "$W/sync" && patch -p1 -s -F0 --no-backup-if-mismatch < ../sg.patch) || fail "syncSweepGuard patch does not apply (zero fuzz)"; fi
m=$(md5of "$W/src/standalone.js"); [ "$m" = "$SA_AFTER" ] || fail "patched standalone.js md5 $m, expected $SA_AFTER"
m=$(md5of "$W/scripts/run-daily-crawl.mjs"); [ "$m" = "$DR_AFTER" ] || fail "patched run-daily-crawl.mjs md5 $m, expected $DR_AFTER"
m=$(md5of "$W/sync/syncSweepGuard.js"); [ "$m" = "$SG_AFTER" ] || fail "patched syncSweepGuard.js md5 $m, expected $SG_AFTER"
cp "$W/src/standalone.js" "$W/chk1.mjs"; node --check "$W/chk1.mjs" || fail "patched standalone.js does not parse"
cp "$W/scripts/run-daily-crawl.mjs" "$W/chk2.mjs"; node --check "$W/chk2.mjs" || fail "patched driver does not parse"
cp "$W/sync/syncSweepGuard.js" "$W/chk3.mjs"; node --check "$W/chk3.mjs" || fail "patched syncSweepGuard.js does not parse"
# Contract smoke test: the line the crawler's own formatter prints must be read by the sync client's parser as a do-not-sweep store.
out=$(cd "$W" && node --input-type=module -e '
const hg = await import("./src/heapGuard.js"); const sg = await import("./sync/syncSweepGuard.js");
const g = hg.makeHeapGuard({ratio:0.85, reserveBytes:hg.heapReserveBytes(480*1048576), stats:()=>({used_heap_size:3000*1048576,heap_size_limit:3584*1048576}), minIntervalMs:0});
const c = hg.detachStrings({a:"x",d:new Date(1)});
const line = hg.formatHeapStopLine({progress:"[10/24]", name:"Test Store", ...g.snapshot(), count:5});
const e = sg.parseHostileLines(line);
console.log(g.pressured(), c.a, c.d instanceof Date, e.length, e[0] && e[0].name, e[0] && e[0].cls, sg.isHostileClass("HEAP_GUARD"))' 2>&1)
[ "$out" = "true x true 1 Test Store HEAP_GUARD true" ] || fail "contract smoke test gave: $out"
echo "trial ok: standalone.js -> $SA_AFTER, run-daily-crawl.mjs -> $DR_AFTER, syncSweepGuard.js -> $SG_AFTER$([ "$SG_DONE" = 1 ] && echo ' (already)'), contract smoke test ok"
if [ "$MODE" = check ]; then echo "CHECK only, nothing installed. Re-run with 'apply' on Paul's GO."; echo "ROLLBACK: rerun with 'restore' (bash -s -- restore < install.sh)."; exit 0; fi

[ ! -e "$BK/md5s-before.txt" ] || fail "$BK already holds a backup from an earlier run; move it aside first"
mkdir -p "$BK" || fail "cannot make $BK"
cp -p "$SA" "$BK/standalone.js.before"; cp -p "$DRV" "$BK/run-daily-crawl.mjs.before"; cp -p "$SG" "$BK/syncSweepGuard.js.before"
{ echo "$sa standalone.js"; echo "$dr run-daily-crawl.mjs"; echo "$sg syncSweepGuard.js"; } > "$BK/md5s-before.txt"
bad() { echo "FAILED: $*" >&2; cp -p "$BK/standalone.js.before" "$SA"; cp -p "$BK/run-daily-crawl.mjs.before" "$DRV"; cp -p "$BK/syncSweepGuard.js.before" "$SG"; rm -f "$HG"; echo "restored from $BK" >&2; exit 1; }
install -m 644 "$W/src/heapGuard.js" "$HG.new" && mv -f "$HG.new" "$HG" || bad "installing heapGuard.js"
cp -p "$W/src/standalone.js" "$SA.new" && mv -f "$SA.new" "$SA" || bad "installing standalone.js"
cp -p "$W/scripts/run-daily-crawl.mjs" "$DRV.new" && mv -f "$DRV.new" "$DRV" || bad "installing driver"
cp -p "$W/sync/syncSweepGuard.js" "$SG.new" && mv -f "$SG.new" "$SG" || bad "installing syncSweepGuard.js"
[ "$(md5of "$HG")" = "$HG_MD5" ] && [ "$(md5of "$SA")" = "$SA_AFTER" ] && [ "$(md5of "$DRV")" = "$DR_AFTER" ] && [ "$(md5of "$SG")" = "$SG_AFTER" ] || bad "md5 after install"
cp "$SA" "$W/f1.mjs"; node --check "$W/f1.mjs" || bad "installed standalone.js does not parse"
cp "$DRV" "$W/f2.mjs"; node --check "$W/f2.mjs" || bad "installed driver does not parse"
cp "$SG" "$W/f3.mjs"; node --check "$W/f3.mjs" || bad "installed syncSweepGuard.js does not parse"
{ echo "$HG_MD5 heapGuard.js"; echo "$SA_AFTER standalone.js"; echo "$DR_AFTER run-daily-crawl.mjs"; echo "$SG_AFTER syncSweepGuard.js"; } > "$BK/md5s-after.txt"
echo "INSTALLED. backup in $BK; md5s now:"; sed 's/^/  /' "$BK/md5s-after.txt"
echo "No restart: the next crawl / sync is a fresh Node process. ROLLBACK: rerun with 'restore'."
